---@class PagePlayerSampleInfoViewView
PagePlayerSampleInfoView = class("PagePlayerSampleInfoView")
function PagePlayerSampleInfoView:initialize(gameObject, uiModuleID)
    self.gameObject = gameObject
    self.uiModuleID = uiModuleID
    self.playerIcon80 = UIUtil.GetChild("PlayerIcon80", self.gameObject)
    self.BgRoot = UIUtil.GetChild("BgRoot", self.gameObject)
end

---@param data PlayerSampleInfoData
function PagePlayerSampleInfoView:Refresh(data, isHaveFrame)
    self.data = data
    CommonHelper:SetGameObjectActive("PlayerIcon80", self.gameObject, isHaveFrame)
    CommonHelper:SetGameObjectActive("PlayerMask", self.gameObject, not isHaveFrame)
    if isHaveFrame then
        if self.data.headIcon then
            CommonHelper:GetComponentSetUITexture("icon", self.playerIcon80, self.data.headIcon, self.uiModuleID)
        end
        if self.data.iconFrame then
            CommonHelper:GetComponentSetUITexture("iconframe", self.playerIcon80, self.data.iconFrame, self.uiModuleID)
        end
    else
        CommonHelper:GetComponentSetUITexture("PlayerRawImage", self.gameObject, self.data.headIcon, self.uiModuleID)
    end
    CommonHelper:SetGameObjectActive("BgText", self.gameObject, self.data.level>0)
    CommonHelper:SetGameObjectActive("LvText", self.gameObject, self.data.level>0)
    CommonHelper:SetText("###playerNameText", self.gameObject, self.data.roleName)
    CommonHelper:SetText("###LabLV", self.gameObject, tostring(self.data.level))
    CommonHelper:SetGameObjectActive("CupBg1", self.gameObject, false)
    CommonHelper:SetGameObjectActive("CupBg2", self.gameObject, false)
    CommonHelper:SetGameObjectActive("CupBg3", self.gameObject, false)
    CommonHelper:SetGameObjectActive("CupMaskImage1", self.gameObject, self.data.cups[1] and self.data.cups[1] ~= 0)
    CommonHelper:SetGameObjectActive("CupMaskImage2", self.gameObject, self.data.cups[2] and self.data.cups[2] ~= 0)
    CommonHelper:SetGameObjectActive("CupMaskImage3", self.gameObject, self.data.cups[3] and self.data.cups[3] ~= 0)
    if self.data.cups[1] and self.data.cups[1] ~= 0 then
        local cfgIcon1 = CommonHelper:GetTableDataByID(ConfigNames.article_config, self.data.cups[1])
        CommonHelper:GetComponentSetUITexture("CupRawImage1", self.gameObject, cfgIcon1.NewIcon, self.uiModuleID)
    end
    if self.data.cups[2] and self.data.cups[2] ~= 0 then
        local cfgIcon2 = CommonHelper:GetTableDataByID(ConfigNames.article_config, self.data.cups[2])
        CommonHelper:GetComponentSetUITexture("CupRawImage2", self.gameObject, cfgIcon2.NewIcon, self.uiModuleID)
    end
    if self.data.cups[3] and self.data.cups[3] ~= 0 then
        local cfgIcon3 = CommonHelper:GetTableDataByID(ConfigNames.article_config, self.data.cups[3])
        CommonHelper:GetComponentSetUITexture("CupRawImage3", self.gameObject, cfgIcon3.NewIcon, self.uiModuleID)
    end
    if self.data.isDynamicBg then
        self:LoadAsyncBgPrefab()
        --self:LoadBgPrefab()
    else
        CommonHelper:GetComponentSetUITexture("BgRawImage", self.gameObject, self.data.bgIcon, self.uiModuleID)
    end
    CommonHelper:SetGameObjectActive("BgRawImage", self.gameObject,not self.data.isDynamicBg)
    CommonHelper:SetGameObjectActive("BgRoot", self.gameObject, self.data.isDynamicBg)
end

function PagePlayerSampleInfoView:LoadBgPrefab()
    if self.dynamicDic == nil then
        self.dynamicDic = {}
        self.AssetDic = {}
    end
    if self.dynamicDic[self.data.bgIcon] == nil then
        local prefabName = string.format("%s.prefab",self.data.bgIcon)
        self.AssetDic[self.data.bgIcon] = AssetsManager.Load(prefabName, typeof(GameObject))
        self.dynamicDic[self.data.bgIcon]= CommonHelper:InstantiateGameObjectByObject(self.AssetDic[self.data.bgIcon].asset)
        UIUtil.SetParentTransform(self.BgRoot.transform,self.dynamicDic[self.data.bgIcon],true)
        local uIParticle  = UIUtil.GetGameobjectComponent(self.dynamicDic[self.data.bgIcon] , typeof(CS.Coffee2.UIExtensions.UIParticle))
        if uIParticle then
            local scale= 1/self.gameObject.transform.localScale.x * uIParticle.scale3D.z
            uIParticle.scale3D = Vector3 (scale,scale,uIParticle.scale3D.z)
        end
    end
    for key, prefab in pairs(self.dynamicDic) do
        if  not GameObjectIsNull(prefab)  then
            CommonHelper:CSGameObjectSetActive(prefab,  key == self.data.bgIcon)
        end
    end
end

function PagePlayerSampleInfoView:LoadAsyncBgPrefab()
    if self.dynamicDic == nil then
        self.dynamicDic = {}
        self.AssetDic = {}
    end
    if self.AssetDic[self.data.bgIcon] == nil then
        local prefabName = string.format("%s.prefab",self.data.bgIcon)
        self.AssetDic[self.data.bgIcon] = AssetsManager.LoadAsync(prefabName, typeof(GameObject))
        self.AssetDic[self.data.bgIcon]:AddComplete(function(asset)
            if self.dynamicDic~=nil and asset ~= nil and asset.asset ~= nil then
                self.dynamicDic[self.data.bgIcon] = CommonHelper:InstantiateGameObjectByObject(asset.asset)
                UIUtil.SetParentTransform(self.BgRoot.transform,self.dynamicDic[self.data.bgIcon],true)
                local uIParticle  = UIUtil.GetGameobjectComponent(self.dynamicDic[self.data.bgIcon] , typeof(CS.Coffee2.UIExtensions.UIParticle))
                if uIParticle and uIParticle.scale3D.z> 0 then
                    local scale=1
                    if uIParticle.scale3D.z>0.99 then
                        scale = 1/self.gameObject.transform.localScale.x * uIParticle.scale3D.z
                    else
                        scale = self.gameObject.transform.localScale.x * uIParticle.scale3D.z
                    end
                    uIParticle.scale3D = Vector3 (scale,scale,uIParticle.scale3D.z)
                end

            end
        end)
    end


    for key, prefab in pairs(self.dynamicDic) do
        if  not GameObjectIsNull(prefab)  then
            CommonHelper:CSGameObjectSetActive(prefab,  key == self.data.bgIcon)
        end
    end
end

function PagePlayerSampleInfoView:ClearCacheBgPrefab()
    if self.dynamicDic then
        for name, obj in pairs(self.dynamicDic) do
            if not GameObjectIsNull(obj) then
                GameObject.Destroy(obj)
            end
            if self.AssetDic[name] ~= nil then
                AssetsManager.Unload(self.AssetDic[name])
            end
        end
    end
    self.dynamicDic = nil
    self.AssetDic = nil
end

function PagePlayerSampleInfoView:Clear()
    self:ClearCacheBgPrefab()
end
